// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Drone".

The composer uses Yota Morimoto's Ambient Sound Generator

https://yota.tehis.net/asg/

The shader is just some sort of psychedelic nonsense that
accompanies the hum of the sound generator and, over time,
proves just as unbearable.

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time

*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2981523/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
	Composer()
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, .05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define S smoothstep
#define N normalize
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
float rnd(float a) {
	vec2 p=fract(a*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
float disc(vec3 p, vec2 s, float r) {
	vec2 c=vec2(length(p.xy)-s.x+r,abs(p.z)-s.y+r);
	return length(max(c,.0))+min(.0,max(c.x,c.y))-r;
}
float map(vec3 p) {
	float d=5e5, k=40., steps=5.;
	vec3 q=p;
	q.xy*=rot(T*.2);
	for (float i=.0; i++<steps;) {
		q.z-=i*.5;
		vec3 st=q;
		st.z-=2e-4*distance(cos(st.x*k),sin(st.y*k));
		float e=disc(st,vec2(5e5,.1),.0), f=cos(8.*atan(q.x-.2,q.y+.2));
		f*=f*f*f*f*f*f*f;
		float a=disc(q-vec3(.2,-.2,.0),vec2(1.+.25*exp(-f),1),.0);
		d=min(d,smin(e,-a,-.0125));
		q.xy*=rot(6.28318/steps);
	}
	return d;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1)*.5773;
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
float calcAO(vec3 p, vec3 n) {
	float occ=.0, sca=1.;
	for (float i=.0; i<5.; i++) {
		float
		h=.01+i*.09,
		d=map(p+h*n);
		occ+=(h-d)*sca;
		sca*=.55;
		if (occ>.35) break;
	}
	return clamp(1.-3.*occ,.0,1.)*(.5+.5*n.y);
}
float shadow(vec3 p, vec3 lp) {
	float shd=1., maxd=distance(lp,p);
	vec3 l=N(lp-p);
	for (float i=1e-2; i<maxd;) {
		float d=map(p+l*i);
		if (abs(d)<1e-2) {
			shd=.0;
			break;
		}
		shd=min(shd,32.*d/i);
		i+=d;
	}
	return shd;
}
float poly(vec2 p, float n) {
	float
	a=atan(p.x,p.y),
	b=6.28318/n;
	return cos(floor(.5+a/b)*b-a)*length(p);
}
vec3 pattern(vec2 uv, float t) {
	vec2 p=uv*.05;
	vec3 col=vec3(0);
	for (float i=.0; i<5.; i++) {
		p=fract(p*2.05)-.5;
		float d=poly(p,8.)/(.25+dot(p,p));
		d=sin(d*9.+t+i)*.25;
		d=abs(d);
		col+=.02/d*hue(length(uv)+i*.125-t*.125);
	}
	return col;
}
bool march(inout vec3 p, vec3 rd) {
	float dd;
	for (int i; i++<100;) {
		float d=map(p);
		if (abs(d)<1e-3) return true;
		if (dd>10.) return false;
		p+=rd*d;
		dd+=d;
	}
}
vec3 render(vec3 p, vec3 rd, float t) {
	vec3 col;
	if (march(p,rd)) {
		vec3 n=norm(p), lp=vec3(1,2,-4), l=N(lp), refl=reflect(rd,n);
		float dif=clamp(dot(l,n),.0,1.), spe=pow(clamp(dot(refl,l),.0,1.),8.),
		shd=shadow(p+n*5e-2,lp);
		vec3 mat=hue(t+p.z*.1+.5)+(n.z<-.99?.2*pattern(p.xy*rot(T*.2+cos(6.3/5.*p.z+.5)),p.z+t):vec3(0));
		mat/=1.+exp(-mat);
		col+=.2*mat+dif*mat*mix(.5,1.,rnd(shd));
		col+=spe*mat*.5+spe*.5;
		col+=.2*refl;
		col+=.2*pattern(refl.xy,-t*.1);
		col*=calcAO(p,n);
		col=tanh(col);
	} else {
		col=hue(rd.z+t)+.2*pattern(rd.xy*5.*rot(T*.2),t);
	}
	return col;
}
void main() {
	float t=mix(T,T+1.,sin(T+2.)*.5+.5);
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,exp(-cos(t*.2)*2.2)-2.),
	rd=N(vec3(uv,1));
	col=render(p,rd,t);
	col=tanh(col*col);
	col=sqrt(col);
	col=clamp(col,.08,.92);
	col*=.8;
	uv=.6*(FC/R*2.-1.);
	col=mix(col,vec3(0),pow(dot(uv,uv),.8));
	O=vec4(col,1);
}

