const choose = a => a[Math.floor(Math.random() * a.length)]
const speeds = [.82]
const resont = [.38]
const volmns = [1, .8, .5]
const options = {
	volume: choose(volmns),
	resonance: choose(resont),
	speed: choose(speeds),
	rand: 1
}

const Composer = () => {
	let context,
		main, verb, bus, compressor

	const trigger = Object.freeze({
		trig: function() {
			let prev = 0
			let t = false
			return function(val) {
				t = prev < 0 && val >= 0
				prev = val
				return t
			}
		},
		change: function() {
			var prev = 0
			var t = false
			return function(val) {
				t = prev != val
				prev = val
				return t
			}
		},
		pulse: function(threshold) {
			var prev = 0
			var t = false
			return function(b) {
				if (b) prev++
				if (prev == threshold) {
					t = true
					prev = 0
				} else {
					t = false
				}
				return t
			}
		},
		skip: function(n) {
			let count = 0
			return function(b) {
				return count++ % n == 0
			}
		}
	})

	const melodicminor = [0, 2, 3, 5, 7, 9, 11]
	const locrian = [0, 1, 3, 5, 6, 8, 10]
	const phrygian = [0, 1, 3, 5, 7, 8, 10]
	const aeolian = [0, 2, 3, 5, 7, 8, 10]
	const dorian = [0, 2, 3, 5, 7, 9, 10]
	const ionian = [0, 2, 4, 5, 7, 9, 11]
	const mixolydian = [0, 2, 4, 5, 7, 9, 10]
	const lydian = [0, 2, 4, 6, 7, 9, 11]
	const mode = [melodicminor, locrian, phrygian, aeolian, dorian, ionian, mixolydian, lydian]
	const lowTrig = trigger.trig()
	const highTrig = trigger.trig()
	const bassTrig = trigger.trig()
	const lowChanged = trigger.change()
	const highChanged = trigger.change()
	const bcChanged = trigger.change()
	const bassChanged = trigger.change()
	const pulseTrig = trigger.trig()
	const pulsed = trigger.pulse(30)
	const every = trigger.skip(1)
	const everyOther = trigger.skip(3)
	const everyOther2 = trigger.skip(5)
	const everyOther3 = trigger.skip(15)
	const everyOther4 = trigger.skip(7.5)

	const roots = [21, 23, 24, 26, 28, 30]

	let b = [-1, -.5, 0, .5, 1, .5, 0, -.5]
	b = [...b, ...b, ...b, ...b]
	b = [...b, ...b, ...b, ...b]
	let m = [0, 4, 0, 9, 0, 4, 9]
	let bb = b
	let root = pickItem(b[1], 0, 20, roots)
	let then = 0

	options.rand = lerp(b[2], -1, 1, 0.05, 1)

	function loop(now) {
		if (every(bb[2]))
			sine(
				midicps(pickNote(bb[21], 10, 30)),
				pickVolume(21, -12, -12),
				bb[23]
			)
		if (every(bb[4]))
			tri(
				midicps(pickNote(bb[21], 10, 30)),
				pickVolume(21, -12, -12),
				bb[23]
			)
		if (every(bb[5]))
			sine(
				midicps(pickNote([.5], 12, 27)),
				pickVolume(21, -12, -12),
				1
			)
		compose()
		hack(
			midicps(pickNote([-10], 6, 30)),
			pickVolume(11, -17, -12),
			b[23]
		)
		saw(
			midicps(pickNote([-10], 6, 30)),
			pickVolume(11, -15, -20),
			b[23]
		)

		setTimeout(() => loop(), expInterp(options.speed, 0, 1, 800, 80))
	}

	function compose() {
		fire = Float32Array.from({
			length: 24
		}, () => Math.random() * 2 - 1)
		for (let i = 0; i < b.length; i++) {
			b[i] = -b[mod(i + 1, b.length)]
		}

		if (pulsed(pulseTrig(b[0]))) {
			root = choose(roots)

			if (everyOther3(b[0])) {
				const note = pickNote(b[21], 10, 30)

				sine(
					midicps(note),
					pickVolume(b[22], -24, -9),
					b[23]
				)
				sine(
					midicps(pickNote(b[22], 10, 30)),
					pickVolume(b[22], -24, -9),
					b[23]
				)
				sine(
					midicps(pickNote(b[23], 15, 35)),
					pickVolume(b[22], -24, -9),
					b[23]
				)
			}

			if (every(b[2])) {
				var note = pickNote(b[21], 10, 20)
				hack(
					midicps(note),
					pickVolume(b[22], -24, -9),
					b[23]
				)
			}
			if (bassTrig(b[21])) {
				hack(
					midicps(pickNote(b[21], 5, 20)),
					pickVolume(21, -12, -12),
					b[23]
				)
			}
			if (every(b[22])) {
				hack(
					midicps(pickNote(b[22], 5, 15)),
					pickVolume(21, -12, -12),
					b[23]
				)
			}
		}

	}

	function juggle(a) {
		if (a < 0) {
			return Math.random() - .5
		}
		return Math.random() * 2 - 1
	}

	function pickItem(v, a, b, array) {
		return array[round(lerp(v, -1, 1, a, b)) % (array.length - 1)]
	}

	function pickNote(v, a, b) {
		return deg2key(lerp(v, -1, 1, a, b), m) + root
	}

	function pickVolume(v, a, b) {
		return dbamp(lerp(v, -1, 1, a, b))
	}

	function mod(n, m) {
		return ((n % m) + m) % m
	}

	function div(a, b) {
		return a / b >> 0
	}

	function deg2key(degree, mode) {
		const size = mode.length
		const deg = round(degree)
		return (12 * div(deg, size)) + mode[mod(deg, size)]
	}

	function fractInterp(a, b, fraction) {
		return a + fraction * (b - a)
	}

	function expInterp(x, a, b, c, d) {
		if (x <= a) {
			return c
		}
		if (x >= b) {
			return d
		}
		return Math.pow(d / c, (x - a) / (b - a)) * c
	}

	function lerp(x, a, b, c, d) {
		if (x <= a) {
			return c
		}
		if (x >= b) {
			return d
		}
		return (x - a) * (d - c) / (b - a) + c
	}

	function round(a) {
		return (a + (a > 0 ? 0.5 : -0.5)) << 0
	}

	function midicps(a) {
		return 440. * Math.pow(2.0, (a - 69.0) * 0.083333333333)
	}

	function dbamp(a) {
		return Math.pow(10, a * 0.05)
	}

	function createReverb(context) {
		const length = 6 * context.sampleRate
		const decay = .8
		const buffer = context.createBuffer(2, length, context.sampleRate)
		const noiseData = [buffer.getChannelData(0), buffer.getChannelData(1)]

		const noise = Float32Array.from({
			length
		}, () => Math.random() * 2 - 1)

		for (let i = 0; i < length; i++) {
			const k = noise[i]
			noiseData[0][i] = k * Math.pow(1 - i / length, decay)
			noiseData[1][i] = k * Math.pow(1 - i / length, decay)
		}

		const convolver = context.createConvolver()
		convolver.buffer = buffer

		return convolver
	}

	function init() {
		window.AudioContext = window.AudioContext || window.webkitAudioContext || window.mozAudioContext || window.oAudioContext
		context = new AudioContext({
			latencyHint: 'balanced'
		})

		verb = createReverb(context)
		compressor = context.createDynamicsCompressor()
		main = context.createGain()
		bus = context.createGain()
		bus.connect(verb)
		verb.connect(main)
		main.connect(compressor)
		compressor.ratio.value = 12
		compressor.release.value = .25
		compressor.threshold.value = -25
		compressor.connect(context.destination)

		console.table(options)

		requestAnimationFrame(loop)
	}

	function instrument(freq, amp, pan, type, att, rel, detune) {
		const HALF_PI = Math.PI * 0.5
		const vco = context.createOscillator()
		const vca = context.createGain()
		const out = context.createGain()
		const panner = context.createStereoPanner()
		panner.pan.value = pan
		vco.detune.value = detune
		vco.type = type //triangle, sine, square, sawtooth, custom
		vco.frequency.value = freq
		// filter
		const filter = context.createBiquadFilter()
		filter.type = "peaking"
		filter.gain.value = -80
		filter.connect(out.gain)
		// lfo
		const lfo = context.createOscillator()
		lfo.frequency.setValueAtTime(freq, context.currentTime)
		lfo.connect(filter)
		// xfade resonance
		out.gain.value = Math.cos(options.resonance * HALF_PI)
		bus.gain.value = Math.cos((1.0 - options.resonance) * HALF_PI)
		vco.connect(vca)
		vca.connect(panner)
		panner.connect(out)
		out.connect(main)
		panner.connect(bus)
		// env
		const now = context.currentTime
		const attack = now + att
		const release = attack + rel
		vca.gain.value = 0
		vca.gain.setValueAtTime(vca.gain.value, now)
		vca.gain.linearRampToValueAtTime(amp, attack)
		vca.gain.exponentialRampToValueAtTime(0.001, release)
		vco.start(now)
		lfo.start(now)
		// gc
		vco.stop(release + 0.1)
		lfo.stop(release + .1)
		setTimeout(() => {
			lfo.disconnect()
			vco.disconnect()
		}, 1000 * (release + 0.2))
	}

	function sine(freq, amp, pan) {
		instrument(freq, amp, pan, 'sine', .01, 1.5, 0)
	}

	function tri(freq, amp, pan) {
		instrument(freq, amp, pan, 'triangle', .01, .5, 0)
	}

	function saw(freq, amp, pan) {
		instrument(freq, amp, pan, 'sawtooth', .025, .5, 5)
	}

	function hack(freq, amp, pan) {
		for (let i = 1; i < 4; i++) {
			instrument(freq * i, amp, pan, 'sine', .025, .125, i)
		}
	}

	init()
}

